

const LOCK={"n":150000,"w":[{"s":"j9OhZ+4e5Ah4Zjq5pLl32A==","i":"mzSkS7OdU9X5fza6","k":"yCWOo6YZ6ghFg+meWzau0zweU7qxiGCinBqsj1xO2miq5mPc1hTroHGub/CLXysp"}],"i":"fpZjqrrEPGAUeVyl","d":""};
let TESTS=[];
const ub=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function unlockTests(code){
  code=String(code||'').trim().toUpperCase();if(!code)return false;
  if(!(window.crypto&&crypto.subtle))throw new Error('nocrypto');
  const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(code),'PBKDF2',false,['deriveKey']);
  for(const w of LOCK.w){
    try{const wk=await crypto.subtle.deriveKey({name:'PBKDF2',salt:ub(w.s),iterations:LOCK.n,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['decrypt']);
      const raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:ub(w.i)},wk,ub(w.k));
      const k=await crypto.subtle.importKey('raw',raw,'AES-GCM',false,['decrypt']);
      const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:ub(LOCK.i)},k,ub(LOCK.d));
      TESTS=JSON.parse(new TextDecoder().decode(pt));return true}catch(e){}
  }
  return false;
}
