/* ================== STORAGE + CLOUD ================== */
function loadLocal(key){try{return JSON.parse(store(STORE+'s:'+key)||'null')}catch(e){return null}}
function save(push){if(!S)return;S.updated=Date.now();store(STORE+'s:'+S.key,JSON.stringify(S));if(push)pushCloud()}
let pushT=null;
function pushCloud(){if(!CLOUD_URL||!S)return;S.unsynced=true;store(STORE+'s:'+S.key,JSON.stringify(S));clearTimeout(pushT);pushT=setTimeout(doPush,400)}
async function doPush(){if(!CLOUD_URL||!S)return;const snap=JSON.parse(JSON.stringify(S));delete snap.unsynced;
  try{const r=await fetch(CLOUD_URL,{method:'POST',body:JSON.stringify({action:'save',app:APP,key:S.key,data:snap})});const j=await r.json();if(j.ok){S.unsynced=false;store(STORE+'s:'+S.key,JSON.stringify(S));updSync()}}catch(e){updSync()}}
async function cloudGet(params,timeout=9000){const ctl=new AbortController();const t=setTimeout(()=>ctl.abort(),timeout);
  try{const r=await fetch(CLOUD_URL+'?'+new URLSearchParams(params),{signal:ctl.signal});return await r.json()}finally{clearTimeout(t)}}
function done(D){return TESTS.filter(t=>D.tests[t.id]&&D.tests[t.id].kwt).length+TESTS.filter(t=>D.tests[t.id]&&D.tests[t.id].res).length}
async function syncFromCloud(){if(!CLOUD_URL||!S)return;try{const j=await cloudGet({action:'get',app:APP,id:S.key});const c=j&&j.student;
  if(c&&c.updated&&(!S.updated||c.updated>S.updated)&&!S.unsynced){const keepProg={};Object.entries(S.tests).forEach(([k,v])=>{if(v.prog&&!(c.tests[k]&&c.tests[k].res))keepProg[k]=v.prog});S=c;Object.entries(keepProg).forEach(([k,p])=>{S.tests[k]=S.tests[k]||{};S.tests[k].prog=p});store(STORE+'s:'+S.key,JSON.stringify(S));return true}
  if(S.unsynced||!c)pushCloud();}catch(e){}return false}
function updSync(){const c=$('#syncChip');if(!c)return;if(!CLOUD_URL){c.className='syncchip';c.innerHTML='💾 Saved on this device';return}
  c.className='syncchip '+(S.unsynced?'warn':'ok');c.innerHTML=S.unsynced?'⚠️ Not sent yet — check internet':'☁️ Sent to teacher ✓'}

