async function studentLogin(name,group,cont){
  name=cleanName(name);
  const parts=name.split(' ').filter(w=>w.replace(/[^A-Za-z]/g,'').length>=2);
  if(parts.length<2){toast('Ism va familiyani yozing · Write name + surname');const i=$('#inName');if(i)i.focus();return}
  name=name.split(' ').map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' ');
  const key=nameKey(name);
  S=loadLocal(key)||{key,name,group:'',tests:{},created:Date.now(),updated:0};
  S.name=name;group=cleanName(group);if(group)S.group=group;
  Object.values(S.tests).forEach(d=>{if(d.prog&&d.prog.seg)d.prog.seg=null});
  if(CLOUD_URL){$('#loginMsg').innerHTML='<div class="loading"><div class="spin"></div>Loading your results…</div>';await syncFromCloud()}
  save(!cont);store(STORE+'last',key);U={role:'student',key};store(STORE+'session',JSON.stringify(U));
  enterApp();go('#/home',true);
}
