/* ================== ROUTER ================== */
function go(h,replace){if(location.hash===h){route();return}if(replace){history.replaceState(null,'',h);route()}else location.hash=h}
window.addEventListener('hashchange',route);
function setBack(parent,label){ui.parent=parent;const b=$('#backBtn');b.classList.toggle('hide',!parent);b.innerHTML=`<span class="ar">←</span>${label||'Orqaga'}`;}
function route(){
  leaveTest();hidePop();closeModals();window.scrollTo(0,0);
  if(!U){showLogin();return}
  const h=location.hash.replace(/^#\/?/,'').split('/');
  if(U.role==='teacher'){
    if(h[0]==='teacher'&&h[1]==='s'&&h[2])teacherStudent(decodeURIComponent(h[2]));
    else teacherHome();
    return;
  }
  const id=+h[1];
  if(['test','result','kwt','table'].includes(h[0])&&!T(id)){go('#/home',true);return}
  const d=id&&S.tests[id]||{};
  switch(h[0]){
    case'test':if(d.res){go('#/result/'+id,true);return}setBack('#/home');cur=id;testView(id);break;
    case'result':if(!d.res){go('#/test/'+id,true);return}setBack('#/home');cur=id;result(id);break;
    case'kwt':if(!d.res){go('#/test/'+id,true);return}setBack('#/result/'+id);cur=id;kwtStep1(id);break;
    case'table':if(!d.kwt){go(d.res?'#/kwt/'+id:'#/test/'+id,true);return}setBack('#/home');cur=id;kwtFinal(id);break;
    case'report':setBack('#/home');report(S,{});break;
    default:setBack(null);home();
  }
}

/* ================== TIME TRACKING ================== */
function liveTest(){return cur&&ui.mode==='test'&&S&&S.tests[cur]&&S.tests[cur].prog&&S.tests[cur].prog.started}
function pauseClock(){if(!liveTest())return;const pr=S.tests[cur].prog;if(pr.seg){pr.acc+=Date.now()-pr.seg;pr.seg=null;save()}}
function resumeClock(){if(!liveTest())return;const pr=S.tests[cur].prog;if(!pr.seg){pr.seg=Date.now();save()}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(liveTest())S.tests[cur].prog.blurs++;pauseClock()}else resumeClock()});
window.addEventListener('pagehide',pauseClock);
function leaveTest(){if(liveTest()){pauseClock();toast('⏸ Test saqlandi — keyin davom ettirasiz · Test saved')}ui.mode=null}

/* ================== STUDENT HOME ================== */
function stats(D){
  const doneT=TESTS.filter(t=>D.tests[t.id]&&D.tests[t.id].res);
  const score=doneT.reduce((a,t)=>a+D.tests[t.id].res.score,0);
  const time=doneT.reduce((a,t)=>a+D.tests[t.id].res.time,0);
  const kw=TESTS.filter(t=>D.tests[t.id]&&D.tests[t.id].kwt);
  const kwOk=kw.reduce((a,t)=>a+D.tests[t.id].kwt.tFirst+D.tests[t.id].kwt.hFirst,0);
  const kwTot=kw.reduce((a,t)=>a+D.tests[t.id].kwt.tTotal+D.tests[t.id].kwt.hTotal,0);
  return{done:doneT,score,time,kw,kwOk,kwTot,complete:kw.length,acc:doneT.length?Math.round(score/(doneT.length*6)*100):0,kwPct:kwTot?Math.round(kwOk/kwTot*100):null};
}
function nextStep(){
  for(const t of TESTS){const d=S.tests[t.id]||{};
    if(d.prog&&d.prog.started&&!d.res)return{t,href:'#/test/'+t.id,em:'⏳',en:`Continue Test ${t.id}`,uz:`${t.id}-testni davom ettiring`};
    if(d.res&&!d.kwt)return{t,href:'#/kwt/'+t.id,em:'🔑',en:`Key Word Table — Test ${t.id}`,uz:`${t.id}-test: kalit so‘zlar jadvali`};}
  const t=TESTS.find(t=>!(S.tests[t.id]&&S.tests[t.id].res));
  return t?{t,href:'#/test/'+t.id,em:'📖',en:`Start Test ${t.id}: ${t.title}`,uz:`${t.id}-testni boshlang`}:null;
}
